from common import *
import numpy as np,pandas as pd
from backtest.scripts.evaluate import eval_ic_multi_pool as ev
def group_output(m,style,seed=None):
    p=m['pools']['all']; arm=p['ensemble'] if seed is None else p['seeds'][str(seed)]
    top=arm['head_regimes'][style]['3']['5']
    ri=m['diagnostic_ensemble_regime_ic'][style] if seed is None else arm['regimes'][style]['h5']
    assert top['n_days']==ri['n_days']
    return dict(net_ann=top['net_ann'],net_sharpe=top['net_sharpe'],net_vol=top['net_ann_vol'],rank_ic=ri['rank_ic_mean'],n=top['n_days'])
def same_holdings(scores,head):
    ds=list(head['5'])
    ix=pd.MultiIndex.from_tuples([(pd.Timestamp(day),symbol) for day in ds for symbol in head['5'][day]],names=scores.index.names)
    z=np.sort(scores.reindex(ix).to_numpy().reshape(-1,5),axis=1)
    assert np.isfinite(z).all()
    return [d for d,t in zip(ds,z[:,1]==z[:,2]) if t]
def replay(label,panel,days):
    port=panel['port'].reindex(days);bench=panel['bench'].reindex(days)
    a=ev.summarize_head_series(port-bench,5,sets=panel['sets'],turnover_days=set(days),k=3,bench=bench,port=port)
    return {k:a.get(k) for k in ('net_ann','net_sharpe','n_days','turnover')}
def main():
    save_source(__file__);d={};good=[];icdays={};base=read(PREVEX/'metrics/v5.json')
    saved=pd.read_pickle(TMP/'official-evaluation-inputs.pkl');yy=saved['labels'][5];trad=saved['tradable']
    week=pd.read_csv(REGIME,index_col=0,parse_dates=True).loc['2020-08-03':'2026-07-23']
    for v in STYLES:
        versions={'v5':(PREVEX,'v5'),'top5':(PREVEX,v),'rankic':(LAST,v),**{a:(BASE,a+'-'+v) for a in ('stop','train','joint')}}
        docs={a:read(path/'metrics'/f'{name}.json') for a,(path,name) in versions.items()}
        rows={a:group_output(m,v) for a,m in docs.items()};target=rows['joint'];records=[]
        rf=BASE/'docs'/f'predictions-joint-{v}.json';ep=read(rf)['ensemble'];check(ep)
        ps=pd.read_pickle(ROOT/ep['path']).iloc[:,0];hd=read(BASE/'data'/f'joint-{v}-formal-heads.json')['ensemble'];ties=same_holdings(ps,hd)
        pdates=week.index[week.style4.eq(v)]
        p1=ev.daily_head_panel(ps,yy,[3],tradable=trad)[3]
        if ties:
            rev_scores=ps.iloc[::-1];rev_labels=yy.reindex(rev_scores.index)
            assert rev_scores.index.equals(rev_labels.index)
            p2=ev.daily_head_panel(rev_scores,rev_labels,[3],tradable=trad)[3]
        else:p2=p1
        fwd=replay(v,p1,pdates);rev=replay(v,p2,pdates)
        for k in ['net_ann','net_sharpe']:assert abs(fwd[k]-target[k])<1e-12
        gate=all(min(fwd[k],rev[k])>rows['v5'][k] for k in ['net_ann','net_sharpe'])
        if gate:good.append(v)
        arms={}
        for a in ['stop','train','joint']:
            arm=a+'-'+v;js=[read(BASE/'docs'/f'{arm}-s{s}.json') for s in SEEDS]
            ctrls={}
            for c in ['rankic','top5','v5']:
                ctrls[c]={k:sum(group_output(docs[a],v,s)[k]>group_output(docs[c],v,s)[k] for s in SEEDS) for k in ('net_ann','net_sharpe','rank_ic')}
            arms[a]=dict(rounds=[j['best'] for j in js],stopped=[j['stopped'] for j in js],ties_at_best=[j['score_at_best']['top3_tie_days'] for j in js],seed_wins=ctrls,reverse_selected=all(j['best']==j['reverse_best'] for j in js))
            src=dict(exp_id=EID+'/'+arm,parent_experiment=EID,state='completed',representative=False,seeds=SEEDS,metrics=rows[a],result_dirs=['backtest/result/'+j['session'] for j in js],portable_eval_output=str((BASE/'metrics'/f'{arm}.json').relative_to(ROOT)),prediction_manifest=fingerprint(BASE/'docs'/f'predictions-{arm}.json'))
            write(BASE/'source-records'/f'{arm}.json',src)
        for a,(path,name) in versions.items():
            if a not in icdays:icdays[a]=[]
            r=pd.read_csv(path/'data'/f'{name}-daily-ic.csv',index_col=0,parse_dates=True).loc[pdates,'rank_ic']
            assert abs(rows[a]['rank_ic']-r.mean())<1e-12;icdays[a].append(r)
        if v=='P':
            bases={}
            for a in ['rankic','top5','v5','joint']:
                path,name=versions[a];daily=pd.read_csv(path/'data'/f'{name}-ensemble-h5-daily.csv',index_col=0,parse_dates=True,float_precision='round_trip')
                sets={pd.Timestamp(d):frozenset(x) for d,x in read(path/'data'/f'{name}-formal-heads.json')['ensemble']['3'].items()}
                panel=dict(port=daily.port,bench=daily.bench,sets=sets)
                bases[a]={w:replay(v,panel,pdates[week.loc[pdates,'period'].ne(w)]) for w in week.loc[pdates,'period'].unique()}
            write(BASE/'metrics/panic-leave-week.json',bases)
        d[v]=dict(metrics=rows,choices=arms,reverse_portfolio=dict(boundary_tie_dates=ties,own_boundary_tie_dates=[t for t in ties if pd.Timestamp(t) in pdates],original=fwd,reverse=rev),qualified=gate)
    avg={}
    for a,series in icdays.items():
        x=pd.concat(series);assert x.index.is_unique and len(x)==1448;avg[a]=x.mean()
    bridges=[read(p) for p in (BASE/'docs').glob('ordinary-*-bridge.json')]
    dif=[b for b in bridges if b['archived_rankic_best']!=b['same_trajectory_rankic_best']]
    write(BASE/'metrics/comparison.json',dict(by_style=d,qualified=good,oracle_style_rankic_daily_weighted=avg,bridge=dict(n=len(bridges),changed_best=len(dif),max_rankic_trace_drift=max(b['max_rankic_difference'] for b in bridges)),new_model_fits=len(read(BASE/'docs/harness-state.json')['jobs']),selected_models=len(read(PROGRESS)['jobs']),control='grade MSE plus pure own-style grade RankIC early stop'))
if __name__=='__main__':main()
